mapper.select:
select c1.C_Name as toCName, c1.C_Abbreviation as toCAbbName, mn.* from SYS_T_Organization mn left join SYS_Company c1 on c1.C_Id = mn.TO_Cid
and mn.Te_Id=#{params.teId}
and mn.TO_Cid=#{params.toCid}
and mn.TO_Status=#{params.toStatus}
and INSTR(mn.TO_Name,#{params.toName})
and INSTR(mn.TO_Create_Uname,#{params.toCreateUname})
and likeCname(#{params.toCName},c1.C_Id)=true
and INSTR(c1.C_Name,#{params.toCName})
order by mn.${params.sortFiled} ${params.sortType}
order by mn.TO_Create_Time DESC
